import json

with open('healthcare_clause_pairs.json') as f:
    data = json.load(f)

print(f'Total pairs: {len(data)}')
print()

# Count by type
from collections import Counter
type_counts = Counter(d['ambiguity_type'] for d in data)
for t, c in sorted(type_counts.items()):
    print(f'  {t}: {c}')

print()

# Verify IDs are sequential within each type
type_ids = {}
for d in data:
    t = d['ambiguity_type']
    if t not in type_ids:
        type_ids[t] = []
    type_ids[t].append(d['clause_id'])

prefix_map = {
    'authorization_scope': 'auth',
    'incompleteness': 'incomp',
    'conditional_precedence': 'cp',
    'lexical': 'lex',
    'scopal': 'scope',
    'coreferential': 'coref'
}

print('ID verification:')
all_ok = True
for t, ids in type_ids.items():
    expected_prefix = prefix_map[t]
    for i, id_ in enumerate(ids, 1):
        expected = f'health_{expected_prefix}_{i:03d}'
        if id_ != expected:
            print(f'  MISMATCH: {id_} != {expected}')
            all_ok = False
    print(f'  {t}: IDs {ids[0]} to {ids[-1]} - OK')

if all_ok:
    print('  All IDs correct!')

print()

# Check all fields present
required = ['clause_id', 'ambiguity_type', 'domain', 'ambiguous_clause', 'unambiguous_clause', 'user_scenario', 'ambiguity_point', 'possible_interpretations']
missing = []
for i, d in enumerate(data):
    for f in required:
        if f not in d:
            missing.append((i, d.get('clause_id','?'), f))
    if 'possible_interpretations' in d and len(d['possible_interpretations']) != 2:
        missing.append((i, d.get('clause_id','?'), 'possible_interpretations count != 2'))

if missing:
    print('Missing fields:')
    for m in missing:
        print(f'  {m}')
else:
    print('All required fields present in all entries.')

# Check domain
domains = set(d['domain'] for d in data)
print(f'Domains: {domains}')

# Check interpretations format
bad_interp = []
for d in data:
    interps = d['possible_interpretations']
    if not interps[0].startswith('Broad:') or not interps[1].startswith('Narrow:'):
        bad_interp.append(d['clause_id'])
if bad_interp:
    print(f'Bad interpretation format: {bad_interp}')
else:
    print('All interpretations have Broad:/Narrow: format.')
"
